const { DateTime, IANAZone } = require("/luxon/src/luxon.js");

function groundTruthDST(ts, zone) {
  // use Intl long time zone name; "Daylight" indicates DST
  const dtf = new Intl.DateTimeFormat("en-US", { timeZone: zone, timeZoneName: "long" });
  const parts = dtf.formatToParts(new Date(ts));
  const tzn = parts.find(p => p.type === "timeZoneName").value;
  return /Daylight/.test(tzn) ? true : (/Standard/.test(tzn) ? false : null);
}

const zones = ["America/Los_Angeles","America/New_York","Europe/London","Europe/Paris","Australia/Sydney","Australia/Adelaide","Pacific/Auckland","America/Santiago","Asia/Tokyo","America/Sao_Paulo","Africa/Cairo","Asia/Tehran","America/Havana","Pacific/Norfolk"];
const years = [1970,1974,1975,1976,1980,1987,1990,2000,2007,2010,2020,2021];
